 static Material Mat(string n,Color c){string p=Art+"/"+n+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(p);if(!m){m=new Material(Shader.Find("Standard"));AssetDatabase.CreateAsset(m,p);}m.color=c;m.enableInstancing=true;return m;}
