 public static void RepairShop(){try{var scene=EditorSceneManager.OpenScene(Scene);Physics.SyncTransforms();var bank=GameObject.Find("MINI175_GrandBayCreditUnion").transform;var shop=GameObject.Find("Market_CLOTHES").transform;var npc=GameObject.Find("NPC_ApparelShop").transform;
 Bounds BoundsOf(Transform t){var rs=t.GetComponentsInChildren<Renderer>().Where(r=>!(r is SkinnedMeshRenderer)).ToArray();var b=rs[0].bounds;foreach(var r in rs)b.Encapsulate(r.bounds);return b;}
 bool Overlap(Bounds a,Bounds b){return a.min.x-.25f<b.max.x&&a.max.x+.25f>b.min.x&&a.min.z-.25f<b.max.z&&a.max.z+.25f>b.min.z;}
 var bounds=BoundsOf(shop);var bankBounds=BoundsOf(bank);var obstacles=Object.FindObjectsByType<Transform>(FindObjectsSortMode.None).Where(t=>t.name.StartsWith("Lalay_House_")||t.name.StartsWith("Lalay_Home_")||t.name.StartsWith("Highland_House_")||t.name.StartsWith("ExpansionHouse_")||(t.name.StartsWith("Market_")&&t!=shop)).Where(t=>t.GetComponentsInChildren<Renderer>().Length>0).Select(BoundsOf).ToList();obstacles.Add(bankBounds);
 var roads=Object.FindObjectsByType<MeshCollider>(FindObjectsSortMode.None).Where(c=>c.name.Contains("Road")).ToArray();var terrain=Object.FindObjectsByType<MeshCollider>(FindObjectsSortMode.None).Where(c=>c.name.Contains("Terrain")).ToArray();
 float GroundAt(Vector3 p){float y=float.NegativeInfinity;foreach(var c in terrain)if(c.Raycast(new Ray(new Vector3(p.x,100,p.z),Vector3.down),out var hit,200))y=Mathf.Max(y,hit.point.y);return y;}
 Vector3 delta=Vector3.zero;bool found=!Overlap(bounds,bankBounds);
 if(!found)foreach(float back in new[]{0f,3f,6f,9f,12f,16f}){foreach(float side in new[]{6f,-6f,9f,-9f,12f,-12f,16f,-16f,20f,-20f,25f,-25f,30f,-30f}){var d=bank.right*side-bank.forward*back;var next=bounds;next.center+=d;if(obstacles.Any(b=>Overlap(next,b)))continue;bool hits=false;foreach(float x in new[]{next.min.x,next.center.x,next.max.x})foreach(float z in new[]{next.min.z,next.center.z,next.max.z})foreach(var r in roads)if(r.Raycast(new Ray(new Vector3(x,100,z),Vector3.down),out _,200))hits=true;if(hits)continue;float y=GroundAt(next.center),oldY=GroundAt(bounds.center);if(float.IsInfinity(y)||float.IsInfinity(oldY))continue;delta=d+Vector3.up*(y-oldY);found=true;break;}if(found)break;}
 if(!found)throw new Exception("No clear clothing shop relocation");shop.position+=delta;npc.position+=delta;Physics.SyncTransforms();if(Overlap(BoundsOf(shop),bankBounds))throw new Exception("Shop overlap remains");
