ic static void Inspect(){EditorSceneManager.OpenScene(Scene);var root=GameObject.Find("MINI175_GrandBayCreditUnion").transform;var lines=new List<string>();foreach(var r in Object.FindObjectsByType<Renderer>(FindObjectsSortMode.None)){if(r.transform.IsChildOf(root)||Vector3.Distance(r.bounds.center,root.position)>16)continue;string path=r.name;for(var p=r.transform.parent;p!=null;p=p.parent)path=p.name+"/"+path;lines.Add(path+" centre="+r.bounds.center+" size="+r.bounds.size);}File.WriteAllLines(Out+"/NeighbourAudit.txt",lines);EditorApplication.Exit(0);} public static void Render(){EditorSceneManager.OpenScene(Scene);var root=GameObject.Find("MINI175_GrandBayCreditUnion").transform;foreach(var c in Object.FindObjectsByType<Camera>(FindObjectsSortMode.None))c.enabled=false;RenderSettings.fog=false;var cam=new GameObject("CreditUnionCamera").AddComponent<Camera>();cam.farClipPlane=500;Shot(cam,"CreditUnion",root.position+root.forward*16+root.right*9+Vector3.up*7,root.position+Vector3.up*2);Shot(cam,"LalayLocation",root.position+root.forward*35+root.right*22+Vector3.up*40,root.position);Debug.Log("MINI175_RENDER_PASS");EditorApplication.Exit(0);}
 static void Shot(Camera c,string n,Vector3 pos,Vector3 target){c.transform.position=pos;c.transform.LookAt(target);c.fieldOfView=55;var rt=new RenderTexture(1400,1000,24);c.targetTexture=rt;c.Render();RenderTexture.active=rt;var tex=new Texture2D(1400,1000,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1400,1000),0,0);tex.Apply();File.WriteAllBytes(Out+"/Renders/"+n+".png",tex.EncodeToPNG());c.targetTexture=null;RenderTexture.active=null;Object.DestroyImmediate(rt);Object.DestroyImmediate(tex);}
